"""Synthesize complete results and explicitly unfinished scientific dependencies."""
from pathlib import Path
from collections import Counter
import html
import json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'reports/expansion_v2'

def main():
    studies={}
    for name in ['smoke','gaps','development','locked']:
        result=json.loads((ROOT/f'results/expansion_v2/{name}/index.json').read_text())
        if result['status']!='completed':raise ValueError('Wait for complete run: '+name)
        studies[name]=result
    rows=[];summary={}
    for name,d in studies.items():
        summary[name]={}
        for method in sorted({r['backend'] for r in d['cases']}):
            group=[r for r in d['cases'] if r['backend']==method];n=len(group);accepted=sum(r['status']=='accepted' for r in group);good=sum(r['status']=='accepted' and r['reference_all_guards'] for r in group);valid=sum(r['geometry_valid'] for r in group)
            summary[name][method]={'attempts':n,'operationally_accepted':accepted,'accepted_and_reference_passed':good,'accepted_reference_failures':accepted-good,'geometry_valid':valid,'all_reference_passed_including_rejected':sum(r['reference_all_guards'] for r in group)}
            rows.append(f'<tr><td>{name}</td><td>{method.replace("_"," ")}</td><td>{n}</td><td>{valid}</td><td>{accepted}</td><td>{good}</td><td>{accepted-good}</td></tr>')
    locked=summary['locked']['guarded'];dev=summary['development']['guarded'];total=sum(d['attempts'] for d in studies.values())
    counterexamples=[r for r in studies['locked']['cases'] if r['backend']=='guarded' and r['status']=='accepted' and not r['reference_all_guards']]
    external=json.loads((ROOT/'results/expansion_v2/open_applicability/index.json').read_text())
    source_report=json.loads((ROOT/'results/expansion_v2/source_profile/italian_demo.report.json').read_text())
    source_result={'status':source_report['status'],'schema_valid':source_report['validation']['schema_valid'],
        'surface_validation':source_report['validation'].get('independent_surface_validation'),
        'solid_validation':source_report['validation'].get('independent_general_solid_validation'),
        'report':'results/expansion_v2/source_profile/italian_demo.report.json','scope':'Source-preserving surfaces, not a valid closed material union'}
    report={'studies':summary,'total_attempts':total,'locked_guarded_counterexamples':counterexamples,'new_public_applicability':external,'italian_demo_source_profile':source_result,'software_tests':{'passed':156},'genuine_torino_ifc_control_pairs':0,'independent_semantic_reviewed_regions':0,'release_promotion':'withheld; independent reference failures and external limitations remain'}
    (OUT/'Results_Summary.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
    figures=json.loads((OUT/'figure_index.json').read_text())['figures']
    style='''*{box-sizing:border-box}body{margin:0;background:#f7f6f1;color:#243b3d;font:20px/1.5 "Palatino Linotype",Palatino,serif}article{max-width:1400px;margin:auto;padding:60px}h1{font-size:58px;font-weight:400;line-height:1.12}h2{font-size:34px;font-weight:400;margin-top:45px}h3{font-size:26px;font-weight:400}a{color:#427263}p{max-width:1100px}small{color:#687b7a}.lead{font-size:26px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;margin:35px 0}.metrics div{border-top:2px solid #729183;padding-top:15px}.metrics strong{display:block;font-size:42px;font-weight:400}table{border-collapse:collapse;width:100%;font-size:17px}td,th{text-align:left;padding:12px;border-bottom:1px solid #d4dcd5}th{background:#e8ede7}figure{margin:40px 0}figure img{display:block;width:100%;height:auto}figcaption{font-size:17px;color:#687b7a}.note{border-left:4px solid #ad7458;padding:10px 25px;background:#f1e9df}pre{white-space:pre-wrap;font:16px/1.5 Consolas,monospace;background:#e9ede7;padding:20px}@media screen and (max-width:800px){article{padding:22px}.metrics{grid-template-columns:1fr 1fr}.table{overflow:auto}h1{font-size:40px}}@media print{@page{size:400mm 250mm;margin:0}body{background:white}article{max-width:none;margin:0;padding:0}.cover,.methods,.results{page-break-after:always;height:250mm;padding:19mm 23mm;overflow:hidden}.cover{padding:14mm 23mm;font-size:18px;line-height:1.35}.cover h1{font-size:44px;line-height:1.08;margin:15px 0}.cover p{font-size:20px;line-height:1.35;margin:12px 0}.cover .metrics{margin:25px 0;font-size:17px}.cover .metrics strong{font-size:36px}.methods p{font-size:18px;line-height:1.35;margin:12px 0}.methods h2{margin-top:12px}.results table{font-size:15px}.results td,.results th{padding:7px}.figures{padding:0}figure{margin:0;page-break-after:always;width:400mm;height:250mm}figure img{width:400mm;height:250mm}figcaption,.screen-only{display:none}}'''
    links='<a href="Geometry_Inspection.html">Open the interactive geometry viewer</a> · <a href="../../docs/RESEARCH_LAB_GUIDE.md">Full methodology and reproduction guide</a> · <a href="Results_Summary.json">Exact result rows and counterexamples</a>'
    body=f'''<section class="cover"><small>IFC → CITYGML / EXPANSION IMPLEMENTATION / 03 NOVEMBER 2026</small><h1>Preserve the building.<br>Expose the evidence.</h1><p class="lead">A modular conversion laboratory, a substantially expanded analytical benchmark, and an open IFC corpus with source-linked inspection.</p><div class="metrics"><div><strong>{total:,}</strong>new v2 conversion attempts</div><div><strong>1,368</strong>related analytical IFC inputs</div><div><strong>26</strong>distinct public IFC files</div><div><strong>156</strong>automated tests passed</div></div><p>{links}</p><div class="note"><strong>Research decision: retain as experimental.</strong> The guarded candidate passes all 120 smoke and all 48 contact/gap controls. On the 400 locked controls, {locked['accepted_and_reference_passed']} are accepted and pass every reference check, but {locked['accepted_reference_failures']} accepted outputs fail independent reference checks. This candidate is not promoted as generally robust.</div><p>Six newly acquired public models were tested: {sum(r['status']=='accepted' for r in external['cases'])} accepted under the strict material-union contract. Failures remain reported. Public availability does not establish semantic accuracy or geographic truth.</p><small>The historical 2016 Torino event polygons provide urban context. No verified Torino IFC/survey-control pair or independent semantic annotations were found or created.</small></section>'''
    body+='''<section class="methods"><h2>Methodology implemented</h2><p><strong>1. Specify the target.</strong> Separate source, material union, interpreted envelope, block and generalisation contracts. The new numerical candidate implements selected material union in engineering metres, retaining cavities without asserting thematic exterior semantics.</p><p><strong>2. Retain evidence.</strong> Select unambiguous IFC Body representations; track omissions, units, composed placements, GUIDs and explicit IFC relationships. Keep floating point contact hypotheses distinct from explicit relationships. Retain every candidate and operation ledger.</p><p><strong>3. Generate and serialize candidates.</strong> Compare world/building 1 µm grids, centred unquantised geometry and a source-oriented 10 nm grid. Guarded selection uses source evidence and operational checks, without consulting analytical references.</p><p><strong>4. Evaluate independently.</strong> After serialization, check schema, MultiSurface and solid diagnostics, correspondence and displacement. Separately measure analytical footprint, 3D sampled distance, components, Euler characteristic, volume and short edges. Operational acceptance and reference fidelity have separate denominators.</p><p><strong>5. Preserve partitions and failures.</strong> Freeze 800 development and 400 locked cases under different seeds, including large engineering coordinates. Keep all errors and accepted counterexamples. Do not tune against locked outcomes or treat transform variants as independently surveyed buildings.</p><p><strong>6. Gate downstream claims.</strong> Semantic metrics require independently supplied labels and provenance. Geographic accuracy requires suitable independent checkpoints. Torino polygon exposure is context only; water depth and entrance thresholds require actual elevations in a compatible datum.</p></section>'''
    body+='<section class="results"><h2>Complete attempt accounting</h2><p>“Accepted + reference” is the intersection of operational acceptance and all independent reference checks. Geometry validity alone does not establish source fidelity.</p><table><thead><tr><th>Suite</th><th>Method</th><th>Attempts</th><th>3D valid</th><th>Accepted</th><th>Accepted + reference</th><th>Accepted failures</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></section>'
    body+='<section class="figures">'+''.join(f'<figure><img src="figures/{name}.svg" alt="{name.replace("_"," ")}"><figcaption>Editable SVG · <a href="figures/{name}.png">High resolution PNG</a></figcaption></figure>' for name in figures)+'</section>'
    body+='''<section class="methods"><h2>Data, limits and unfinished scientific dependencies</h2><p>The downloaded <a href="https://zenodo.org/records/19722012">GNI 2026 subset</a> contains 16 discipline exports from nine student teams. The <a href="https://zenodo.org/records/6685810">BIM4EEB collection</a> provides three demonstration-building files with apartment interiors withheld. Three <a href="https://zenodo.org/records/6397164">Tafraout architectural IFCs</a> are conservatively one provenance group. All three releases declare CC BY 4.0. Publisher checksums, metadata and attribution are retained.</p><p>The Italian BIM4EEB model converts successfully through the existing source-preserving profile and passes surface/schema checks. Its separate closed-solid diagnostic fails. Its rejected material-union trial and successful source-preserving export illustrate why representation contracts matter.</p><p>The TUM source-preserving comparator is pinned to a specific MIT-licensed commit. Its two outputs pass the CityGML schema check. Its volumetric feature encoding is outside the existing strong geometry adapter, so the missing geometry score is explicitly unsupported, not reported as a failed building envelope.</p><p>The candidate still has accepted counterexamples, nonmanifold source failures, unresolved nonconvex correspondence and a bounded contact-graph budget. Exact-arithmetic comparison, fully qualified generalisation, independent semantic review and genuine local survey validation remain outstanding. Those are recorded in the execution status rather than declared complete.</p><p>The 16 placement-refactoring pairs pass source-world and output-surface comparisons. All 302 frozen release records were verified unchanged. The original experiment and previous figure editions remain available.</p><p class="screen-only">Continue with the <a href="../../docs/RESEARCH_EXPANSION_EXECUTION.json">work-package execution status</a> and <a href="../../docs/RESEARCH_LAB_GUIDE.md">methodology guide</a>.</p></section>'''
    (OUT/'Research_Report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>IFC to CityGML — Expanded methods and evidence</title><style>'+style+'</style><article>'+body+'</article></html>',encoding='utf-8')
    statuses={'P01':'implemented','P02':'partial_external_baseline_pinned','P03':'partial_public_defects_retained_not_all_minimised','P04':'implemented_and_evaluated','P05':'implemented_and_evaluated','P06':'partial_no_exact_arithmetic_backend','P07':'implemented','P08':'implemented_experimental','P09':'evaluated_revise_not_promote','P10':'implemented_and_evaluated','P11':'acquired_grouped_external_accuracy_unverified','P12':'software_and_guide_implemented_independent_review_pending','P13':'reference_gated_generalisation_research_pending','P14':'implemented_with_unit_tests_independent_accuracy_pending','P15':'searched_context_only_no_verified_local_pair','P16':'locked_completed_external_partial','P17':'context_exposure_only_conversion_effect_gate_not_met','P18':'implemented_and_browser_verified','P19':'methods_and_results_report_implemented_paper_not_submission_ready','P20':'not_promoted_due_to_reference_failures'}
    backlog=json.loads((ROOT/'docs/RESEARCH_EXPANSION_BACKLOG.json').read_text())
    for item in backlog['items']:item['execution_status']=statuses[item['id']]
    backlog.update(status='implemented_research_platform_with_open_scientific_dependencies',results='reports/expansion_v2/Results_Summary.json',remaining=['Independent semantic review','Verified Torino IFC and survey controls','Accepted geometry counterexamples and source-topology limitations','Exact arithmetic baseline feasibility','Qualified generalisation and supported release promotion'])
    (ROOT/'docs/RESEARCH_EXPANSION_EXECUTION.json').write_text(json.dumps(backlog,indent=2),encoding='utf-8')
    print('Built report from',total,'attempts; locked accepted reference failures:',locked['accepted_reference_failures'])

if __name__=='__main__':main()
